  assistantText = run.candidates[0].content.parts[0].text;
} else if (typeof run.output === 'string') {
  assistantText = run.output;
} else if (run.text) {
  assistantText = run.text;
}

// Check for Google Gemini grounding metadata chunks if present
const groundingChunks = run?.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
const groundingSources = groundingChunks.map(chunk => {
  if (chunk?.web?.uri) {
    return `- [${chunk.web.title || 'Source'}](${chunk.web.uri})`;
  }
  return null;
}).filter(Boolean);

if (groundingSources.length > 0 && (!assistantText || !assistantText.includes('http'))) {
  assistantText = (assistantText ? assistantText + '\n\n' : '') + groundingSources.slice(0, 5).join('\n');
}

return [{ json: { output: assistantText || '' } }];

parameters.content:
## Structured Output 

**Generate Outlines** node is using structured output defined in system prompt in node **LLM Params**. Payload for API call defined in node **Define Schema** where target object schema is defined, see left ->
```json
{
  "articleOutlines": [
    {
      "title": "",
      "markdownOutline": ""
    }
  ]
}
```

## Object Schema for Structured Output 

Using the following schema in **Define Schema** node to define **Generate Outlines** structured output. LLM will return list of sample outlines with `title` and `markdownOutline` properties
```json
{
  "schema": {
        "type": "object",
        "properties": {
          "articleOutlines": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "title": { "type": "string" },
                "markdownOutline": { "type": "string" }
              },
              "required": [ "title", "markdownOutline" ],
              "additionalProperties": false
            }
          }
        },
        "required": [ "articleOutlines" ],
        "additionalProperties": false
      }
}
```

