    .replace(/\u2026/g, "...")
    .replace(/\u00A0/g, " ");

  return str.trim();
}

function stripInTextCitations(text) {
  if (!text) return '';
  let str = text;

  // 1. Remove markdown links where link text is a URL, or generic link/source/ref
  str = str.replace(/\[\s*(?:https?:\/\/[^\s\]]+|link|source|url|ref|citation)\s*\]\([^\)]+\)/gi, '');

  // 2. Remove markdown links keeping just clean anchor text: [Harvard Business Review](http...) -> Harvard Business Review
  str = str.replace(/\[([^\]]+)\]\(https?:\/\/[^\)]+\)/g, '$1');

  // 3. Remove parenthesized or bracketed URLs: (https://...) or [https://...] or (URL: https://...)
  str = str.replace(/\s*[\(\[]\s*(?:URL:\s*)?https?:\/\/[^\s\)\]]+[\)\]]/gi, '');

  // 4. Remove standalone URLs or 'URL: https://...'
  str = str.replace(/\s*(?:URL:\s*)https?:\/\/[^\s\)\],;]+/gi, '');
  str = str.replace(/\s*https?:\/\/[^\s\)\],;]+/gi, '');

  // 5. Remove numeric / footnote citations like [1], [2], (1), (2)
  str = str.replace(/\s*\[\d+\]/g, '');

  // 6. Remove generic citation brackets like [link], [source], [ref]
  str = str.replace(/\[\s*(?:link|source|ref|citation)\s*\]/gi, '');

  // 7. Strip square brackets from publication names: '[GamesRadar+]' -> 'GamesRadar+'
  str = str.replace(/\[([^\]\n]{1,60})\]/g, '$1');

